={{ (() => {
  const raw = $json.body ?? $json ?? {};
  const body = typeof raw === "object" && raw !== null ? raw : {};
  const errors = [];
  const REQUIRED_SCHEMA = {
    type: "object",
    properties: {
      to: { type: "string", pattern: "^\\S+@\\S+\\.\\S+$", description: "Recipient email address" },
      gallery_url: { type: "string", pattern: "^https?://[^/\\s]+/gallery#access=", description: "Private signed gallery URL" },
      expires_at: { type: "string", minLength: 10, description: "ISO expiration timestamp" },
      mode: { type: "string", enum: ["camera", "simulation"], description: "Session provenance mode" },
      session_id: { type: "string", description: "Session identifier" },
      idempotency_key: { type: "string", description: "Delivery idempotency key" }
    },
    required: ["to", "gallery_url", "expires_at"],
    additionalProperties: false
  };
  if (typeof body.to !== "string" || !/^\S+@\S+\.\S+$/.test(body.to.trim())) {
    errors.push({ p: "to", m: "Expected valid recipient email address", d: "Recipient email address" });
  }
  if (typeof body.gallery_url !== "string" || !/^https?:\/\/[^/\s]+\/gallery#access=\S+$/.test(body.gallery_url)) {
    errors.push({ p: "gallery_url", m: "Expected valid private gallery URL with #access= token", d: "Private signed gallery URL" });
  }
  if (typeof body.expires_at !== "string" || body.expires_at.trim().length < 10) {
    errors.push({ p: "expires_at", m: "Expected ISO expiration timestamp string", d: "ISO expiration timestamp" });
  }
  if ("mode" in body && body.mode !== undefined && ["camera", "simulation"].indexOf(body.mode) === -1) {
    errors.push({ p: "mode", m: "Must be camera or simulation", d: "Session provenance mode" });
  }
  if (errors.length === 0) {
    return {
      valid: true,
      validationError: null,
      normalized: {
        to: body.to.trim().toLowerCase(),
        gallery_url: body.gallery_url.trim(),
        expires_at: body.expires_at.trim(),
        mode: body.mode === "simulation" ? "simulation" : "camera",
        session_id: typeof body.session_id === "string" ? body.session_id : "",
        idempotency_key: typeof body.idempotency_key === "string" ? body.idempotency_key : ""
      }
    };
  }
  const lines = errors.map(function (e) { return "• " + e.p + ": " + e.m + (e.d ? " - " + e.d : ""); });
  const details = {};
  for (let i = 0; i < errors.length; i++) {
    if (!(errors[i].p in details)) details[errors[i].p] = errors[i].m;
  }
  return {
    valid: false,
    validationError: "Validation failed (" + errors.length + " issue" + (errors.length > 1 ? "s" : "") + "):\n" + lines.join("\n"),
    details: details,
    requiredSchema: REQUIRED_SCHEMA
  };
})() }}
